export const translations: Record<Language, Record<string, string>> = { en, kk: { ...en, ...kk }, ru: { ...en, ...ru } }
export const savedLanguage = (): Language => { const value = localStorage.getItem('skyline.language'); return value === 'ru' || value === 'en' || value === 'kk' ? value : 'kk' }
void i18n.use(initReactI18next).init({ resources: { kk: { translation: translations.kk }, ru: { translation: translations.ru }, en: { translation: translations.en } }, lng: savedLanguage(), fallbackLng: 'kk', interpolation: { escapeValue: false } })
export const translate = (language: Language, key: string) => String(i18n.t(key, { lng: language, defaultValue: translations[language][key] ?? key }))
export const changeLanguage = (language: Language) => i18n.changeLanguage(language)
export const savedTheme = (): Theme => { const value = localStorage.getItem('skyline.theme'); return value === 'light' || value === 'dark' || value === 'system' ? value : 'system' }
